    global atomics, and a second kernel (kept as "layer_norm_kernel" for
    compatibility) finalizes the statistics and normalizes each segment.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        n = 1
        for d in self.normalized_shape:
            n *= d
        self.n_elements = n
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        x = x.contiguous()
        weight = self.weight.contiguous().to(device=x.device, dtype=x.dtype)
        bias = self.bias.contiguous().to(device=x.device, dtype=x.dtype)
        output = torch.empty_like(x)
        n = self.n_elements
        batch_size = x.numel() // n
        # Split each row's reduction/normalization work across multiple
        # cooperative CTAs to better utilize the GPU when batch_size is
        # small relative to the SM count.
        SEG = 32
        if n < SEG * 4:
            SEG = 1
        seg_size = -(-n // SEG)               # ceil div
        seg_size = ((seg_size + 3) // 4) * 4   # round up to multiple of 4
        num_segments = -(-n // seg_size)       # actual segments needed
        sum_buf = torch.zeros(batch_size, dtype=torch.float32, device=x.device)
        sqsum_buf = torch.zeros(batch_size, dtype=torch.float32, device=x.device)
        module = _get_ptx_module()
        stream = torch.cuda.current_stream(x.device)
        module.launch(
            "layer_norm_reduce_kernel",
            grid=(batch_size, num_segments, 1),
            block=(256, 1, 1),
            arguments=[
                x,
                sum_buf,
                sqsum_buf,
                i32(n),
                u32(seg_size),
            ],
            shared_memory=0,
            stream=stream,
        )
        module.launch(
            "layer_norm_kernel",
            grid=(batch_size, num_segments, 1),
            block=(256, 1, 1),
            arguments=[
                x,
                output,
                weight,
                bias,
                sum_buf,
                sqsum_buf,
                i32(n),
                f32(self.eps),
                u32(seg_size),
            ],
            shared_memory=0,
            stream=stream,
        )
        return output
